 62→  return (
 63→    <Tooltip
 64→      onClose={onClose}
 65→      open={open}
 66→      refEl={refEl}
 67→      setOpen={setOpen}
 68→      triggerEvent="click"
 69→      {...props}
 70→    >
 71→      <ContentWrapper ref={popoverRef}>
 72→        {children}
