 1→import { Component } from "react";
 2→import ErrorFallback from "./ErrorFallback/ErrorFallback";
 3→
 4→type DefaultErrorBoundaryProps = {
 5→  children: React.ReactNode;
 6→  homeURL: string;
 7→};
 8→
 9→/**
10→ * DO NOT USE THIS COMPONENT DIRECTLY INSTEAD USE `ErrorBoundary`.
11→ *
12→ * `DefaultErrorBoundary` is a generic Error Boundary component. This component is used in development builds.
13→ * @param param0 - The props
14→ * @param param0.children - The children
15→ * @param param0.homeURL - The home URL of the application.
16→ * @returns - The wrapped component.
17→ */
18→class DefaultErrorBoundary extends Component<
19→  DefaultErrorBoundaryProps,
20→  { hasError: boolean }
21→> {
22→  constructor(props: DefaultErrorBoundaryProps) {
23→    super(props);
24→    this.state = { hasError: false };
25→  }
26→
27→  static getDerivedStateFromError() {
28→    // Update state so the next render will show the fallback UI.
29→    return { hasError: true };
30→  }
31→
32→  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
33→    console.error({ error, errorInfo });
34→  }
35→
36→  render() {
37→    const { hasError } = this.state;
38→    if (hasError) {
39→      return <ErrorFallback homeURL={this.props.homeURL} />;
40→    }
41→    const { children } = this.props;
42→    return children;
43→  }
44→}
45→
46→export default DefaultErrorBoundary;
47→

 1→import { ErrorBoundary } from "@sentry/react";
 2→import { setScope } from "../../utils/sentry";
 3→import ErrorFallback from "./ErrorFallback/ErrorFallback";
 4→import { refreshOnOldBundleError } from "./utils";
 5→/**
 6→ * DO NOT USE THIS COMPONENT DIRECTLY INSTEAD USE `ErrorBoundary`.
 7→ *
 8→ * `SentryErrorBoundary` is a wrapper around the `ErrorBoundary` component from `@sentry/react`. It sets the scope
 9→ * before capturing the error. This component is used in production builds.
10→ * @param param0 - The props
11→ * @param param0.children - The children
12→ * @param param0.homeURL - The home URL of the application.
13→ * @returns - The wrapped component.
14→ */
15→const SentryErrorBoundary: React.FC<{
16→  children: React.ReactNode;
17→  homeURL: string;
18→}> = ({ children, homeURL }) => (
19→  <ErrorBoundary
20→    beforeCapture={(scope) => {
21→      setScope(scope);
22→    }}
23→    fallback={<ErrorFallback homeURL={homeURL} />}
24→    onError={(error) => refreshOnOldBundleError(error as Error)}
25→  >
26→    {children}
27→  </ErrorBoundary>
28→);
29→
30→export default SentryErrorBoundary;
