import { useState } from 'react';
import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect, waitFor } from 'storybook/test';
import { TreeSelect, ALL_VALUE } from './TreeSelect';
import type { TreeDataEntry } from './TreeSelect';

const sampleData: TreeDataEntry[] = [
  { title: 'All', value: ALL_VALUE, key: 'all' },
  {
    title: 'Fruits',
    value: 'fruits',
    key: 'fruits',
    children: [
      { title: 'Apple', value: 'apple', key: 'apple' },
      { title: 'Banana', value: 'banana', key: 'banana' },
      { title: 'Cherry', value: 'cherry', key: 'cherry' },
    ],
  },
  {
    title: 'Vegetables',
    value: 'vegetables',
    key: 'vegetables',
    children: [
      { title: 'Carrot', value: 'carrot', key: 'carrot' },
      { title: 'Broccoli', value: 'broccoli', key: 'broccoli' },
    ],
  },
];

const meta = {
  component: TreeSelect,
  tags: ['ai-generated'],
} satisfies Meta<typeof TreeSelect>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  render: () => {
    const [state, setState] = useState<string[]>([]);
    return <TreeSelect state={state} tData={sampleData} onChange={setState} />;
  },
  play: async ({ canvas }) => {
    await expect(canvas.getByText('All')).toBeVisible();
    await expect(canvas.getByText('Fruits')).toBeVisible();
    await expect(canvas.getByText('Vegetables')).toBeVisible();
  },
};

export const WithPreselected: Story = {
  render: () => {
    const [state, setState] = useState<string[]>(['apple', 'banana']);
    return <TreeSelect state={state} tData={sampleData} onChange={setState} />;
  },
  play: async ({ canvas }) => {
    const appleCheckbox = canvas.getByLabelText('Apple');
    const bananaCheckbox = canvas.getByLabelText('Banana');
    await expect(appleCheckbox).toBeChecked();
    await expect(bananaCheckbox).toBeChecked();
  },
};

export const AllSelected: Story = {
  render: () => {
    const allValues = [ALL_VALUE, 'fruits', 'apple', 'banana', 'cherry', 'vegetables', 'carrot', 'broccoli'];
    const [state, setState] = useState<string[]>(allValues);
    return <TreeSelect state={state} tData={sampleData} onChange={setState} />;
  },
  play: async ({ canvas }) => {
    const allCheckbox = canvas.getByLabelText('All');
    await expect(allCheckbox).toBeChecked();
  },
};

export const ToggleCheckbox: Story = {
  render: () => {
    const [state, setState] = useState<string[]>([]);
    return <TreeSelect state={state} tData={sampleData} onChange={setState} />;
  },
  play: async ({ canvas, userEvent }) => {
    const appleCheckbox = canvas.getByLabelText('Apple');
    await expect(appleCheckbox).not.toBeChecked();
    await userEvent.click(appleCheckbox);
    await waitFor(() => {
      expect(canvas.getByLabelText('Apple')).toBeChecked();
    });
  },
};

content.thinking:
For Popconfirm, the issue is that Popconfirm wraps a `Tooltip` component which renders as a `<span>`. The Popconfirm doesn't render a visible trigger element on its own - it needs a `refEl` to attach to. Looking at the Popconfirm code more carefully:

```tsx
<Tooltip
  onClose={onClose}
  open={open}
  refEl={refEl}
  setOpen={setOpen}
  triggerEvent="click"
  {...props}
>
```

The LeafyGreen Tooltip renders a trigger element. When no children trigger is provided (the children are the tooltip CONTENT), it creates an internal trigger.


Actually, I need to reconsider how the Tooltip API works here - in LeafyGreen, the `children` prop serves as the trigger element itself, not the tooltip content, which means the Popconfirm's children should be what users interact with to open the confirmation dialog. I'm seeing that the `...props` spreads through to the Tooltip component, which means I can pass a `trigger` prop directly to Popconfirm. Since LeafyGreen's Tooltip needs either a trigger element or a refEl to work properly, I should provide one of these in the story to make the component actually display.

