export const CssCheck: Story = {
  args: {
    title: 'CSS Check Accordion',
    children: 'Verifying CSS is loaded.',
  },
  play: async ({ canvas }) => {
    const toggle = canvas.getByText('CSS Check Accordion').closest('[data-cy="accordion-toggle"]')!;
