 6→import { Body } from "@leafygreen-ui/typography";
 7→import { useOnClickOutside } from "../../../../hooks";
 8→import { PopoverContainer } from "../../../styles/Popover";
 9→import { TreeDataEntry, TreeSelect } from "../../../TreeSelect";
10→import { DEFAULT_SPACING, FilterWrapper } from "../constants";
11→
12→const { blue, gray } = palette;
13→
14→interface TableFilterPopoverProps {
15→  "data-cy"?: string;
16→  onConfirm: (filters: string[]) => void;
17→  options: TreeDataEntry[];
18→  value: string[];
19→}
20→
21→const TableFilterPopover: React.FC<TableFilterPopoverProps> = ({
22→  "data-cy": dataCy,
23→  onConfirm,
24→  options,
25→  value,
26→}) => {
27→  const [active, setActive] = useState(false);
28→  const hasFilters = value.length > 0;
29→  const iconColor = hasFilters ? blue.base : gray.dark2;
30→
31→  const buttonRef = useRef<HTMLButtonElement>(null);
32→  const popoverRef = useRef<HTMLDivElement>(null);
33→
34→  // Handle onClickOutside
35→  useOnClickOutside([buttonRef, popoverRef], () => setActive(false));
36→
37→  const onChange = (newFilters: string[]) => {
38→    onConfirm(newFilters);
39→  };
40→
41→  return (
42→    <FilterWrapper>
43→      <IconButton
44→        ref={buttonRef}
45→        active={active}
46→        aria-label="Table Filter Popover Icon"
47→        data-cy={dataCy}
48→        data-highlighted={hasFilters}
49→        onClick={() => setActive(!active)}
50→      >
51→        <Icon color={iconColor} glyph="Filter" />
52→      </IconButton>
53→      <Popover
54→        active={active}
55→        align={Align.Bottom}
56→        justify={Justify.Middle}
57→        refEl={buttonRef}
58→        spacing={DEFAULT_SPACING}
59→      >
60→        <PopoverContainer ref={popoverRef} data-cy={`${dataCy}-wrapper`}>
61→          {options.length > 0 ? (
62→            <TreeSelect onChange={onChange} state={value} tData={options} />
63→          ) : (
64→            <Body>No filters available.</Body>
65→          )}
66→        </PopoverContainer>
67→      </Popover>
68→    </FilterWrapper>
69→  );
70→};
71→
72→export default TableFilterPopover;
